arguments.command:
python3 - <<'PY'
import json, zipfile, re
from pathlib import Path

data = json.load(open('/root/event_data.json', 'r', encoding='utf-8'))

in_path = '/root/event_announcement_template.hwpx'
out_path = '/root/event_announcement_ready.hwpx'

with zipfile.ZipFile(in_path, 'r') as zin:
    names = zin.namelist()
    modified = []
    out_bytes = {}

    for name in names:
        b = zin.read(name)
        # default: pass-through
        try:
            text = b.decode('utf-8')
        except UnicodeDecodeError:
            out_bytes[name] = b
            continue

        if '{{' in text:
            original = text
            for k, v in data.items():
                text = text.replace('{{' + str(k) + '}}', str(v))

            # remove stale layout cache only if changed
            if text != original:
                # observed prefix uses <hp:linesegarray> (lowercase) not lineSegArray
                text = re.sub(r'<hp:linesegarray[^>]*>.*?</hp:linesegarray>', '', text, flags=re.DOTALL)
                modified.append(name)

        out_bytes[name] = text.encode('utf-8')

# residual check before writing
residual = {}
for name, b in out_bytes.items():
    try:
        t = b.decode('utf-8', errors='ignore')
    except Exception:
        continue
    if '{{' in t:
        matches = re.findall(r'\{\{.*?\}\}', t)
        if matches:
            residual[name] = matches

if residual:
    print('WARNING: residual placeholders remain:')
    for n, m in residual.items():
        print(' ', n, m)

# write output zip with mimetype rules
with zipfile.ZipFile(out_path, 'w') as zout:
    if 'mimetype' in names:
        zout.writestr('mimetype', out_bytes['mimetype'], compress_type=zipfile.ZIP_STORED)
    for name in names:
        if name == 'mimetype':
            continue
        zout.writestr(name, out_bytes[name], compress_type=zipfile.ZIP_DEFLATED)

print('Wrote', out_path)
print('Modified:', modified)
PY

